files.style.css:
body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  background: #eef2f7;
  color: #1f2a37;
}
.app {
  max-width: 620px;
  margin: 0 auto;
  padding: 20px;
}
.top h1 { margin: 0 0 4px; font-size: 26px; }
.tag { margin: 0 0 18px; color: #6b7787; font-size: 14px; }
.chat {
  display: flex;
  flex-direction: column;
  height: 340px;
  overflow-y: auto;
  padding: 12px;
  background: #ffffff;
  border: 1px solid #dbe3ec;
  border-radius: 8px;
}
.setup { margin-bottom: 12px; font-size: 14px; }
.setup summary { cursor: pointer; color: #0a6299; font-weight: bold; }
.setup textarea {
  width: 100%;
  margin-top: 8px;
  padding: 9px;
  border: 1px solid #dbe3ec;
  border-radius: 6px;
  font-family: inherit;
  font-size: 14px;
}
.bubble {
  max-width: 78%;
  margin: 0 0 10px;
  padding: 10px 13px;
  border-radius: 12px;
  line-height: 1.5;
  white-space: pre-wrap;
}
.bubble.you {
  margin-left: auto;
  background: #01aefd;
  color: #ffffff;
  border-bottom-right-radius: 3px;
}
.bubble.bot {
  background: #f1f5f9;
  border-bottom-left-radius: 3px;
}
.bubble.problem {
  background: #fff4e0;
  color: #8a5a12;
  font-size: 14px;
}
.composer { display: flex; gap: 8px; margin-top: 12px; }
.composer input {
  flex: 1;
  padding: 11px;
  border: 1px solid #dbe3ec;
  border-radius: 6px;
  font-size: 15px;
}
.composer button {
  padding: 11px 18px;
  border: 0;
  border-radius: 6px;
  background: #01aefd;
  color: #ffffff;
  font-size: 15px;
  cursor: pointer;
}
.controls {
  display: flex;
  gap: 18px;
  flex-wrap: wrap;
  margin-bottom: 12px;
  font-size: 14px;
}
.controls label { display: grid; gap: 4px; }
.controls select, .controls input { font-size: 14px; }
.bubble.writing::after {
  content: "\258C";
  color: #01aefd;
  animation: blink 1s steps(2, start) infinite;
}
@keyframes blink { to { visibility: hidden; } }

