  margin-left: auto;
  background: #01aefd;
  color: #ffffff;
  border-bottom-right-radius: 3px;
}
.bubble.bot {
  background: #f1f5f9;
  border-bottom-left-radius: 3px;
}
.bubble.problem {
  background: #fff4e0;
  color: #8a5a12;
  font-size: 14px;
}
