  padding: 11px 18px;
  border: 0;
  border-radius: 6px;
  background: #01aefd;
  color: #ffffff;
  font-size: 15px;
  cursor: pointer;
}
.controls {
  display: flex;
  gap: 18px;
  flex-wrap: wrap;
  margin-bottom: 12px;
  font-size: 14px;
}
.controls label { display: grid; gap: 4px; }
.controls select, .controls input { font-size: 14px; }
.bubble.writing::after {
  content: "\258C";
  color: #01aefd;
  animation: blink 1s steps(2, start) infinite;
}
@keyframes blink { to { visibility: hidden; } }
.presets { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.preset {
  padding: 5px 11px;
  border: 1px solid #dbe3ec;
  border-radius: 20px;
  background: #ffffff;
  font-size: 13px;
  cursor: pointer;
}
.preset:hover { border-color: #01aefd; color: #0a6299; }

